import{_ as r,a as t,b as i}from"./chunks/74bc758b694d8c0db7e6.3sP7oTf7.js";import{_ as a,C as o,o as s,c as n,j as e,a as m,E as h,a5 as u}from"./chunks/framework.DNkHA0lr.js";const P=JSON.parse('{"title":"打造一人企业最快的方法（新手指南）","description":"","frontmatter":{"title":"打造一人企业最快的方法（新手指南）","originalTitle":"The Fastest Way To Build A One-Person Business (Beginner Guide)","date":"2024-09-07","originalUrl":"https://thedankoe.com/letters/the-minimalist-creator-business-make-your-first-1000-in-60-days/","minutes":24,"sourceHash":"0d57607201a87f5bbe7b7e75b36d0f798624f1c5e61ed117ad8f55561e647a41","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-minimalist-creator-business-make-your-first-1000-in-60-days/"}]]},"headers":[],"relativePath":"letters/the-minimalist-creator-business-make-your-first-1000-in-60-days.md","filePath":"letters/the-minimalist-creator-business-make-your-first-1000-in-60-days.md"}'),d={name:"letters/the-minimalist-creator-business-make-your-first-1000-in-60-days.md"};function c(g,p,f,b,k,_){const l=o("ArticleMeta");return s(),n("div",null,[p[0]||(p[0]=e("h1",{id:"打造一人企业最快的方法-新手指南",tabindex:"-1"},[m("打造一人企业最快的方法（新手指南） "),e("a",{class:"header-anchor",href:"#打造一人企业最快的方法-新手指南","aria-label":'Permalink to "打造一人企业最快的方法（新手指南）"'},"​")],-1)),h(l),p[1]||(p[1]=u('<p><a href="https://www.youtube.com/embed/yddBiuvcaFs?si=Pam5Tr3rSsYaXP-f" target="_blank" rel="noreferrer">观看原文视频</a></p><p><strong>我将给你一份60天的行动计划，帮你赚到第一个1000美元。</strong></p><p>这张图展示的就是你在读完这篇文章后，将学会掌握的内容：</p><p><img src="'+r+'" alt=""></p><p>这篇文章是给新手写的，我觉得60天内赚到1000美元已经相当合理了。但如果你不是新手，凭你将学到的东西，在60天内赚到的远不止这个数。</p><p>我会尽量把这篇文章写得简洁、不废话。但你要明白，关于心态的建议并不是废话。信念和清晰度是技能与自信的前提。</p><p>如果我确实说得有点啰嗦，那是因为我写的这些东西对你来说绝对必要。如果你觉得这部分很枯燥，那很可能正是你会跳过的部分——然后等你没有结果时，又开始抱怨。</p><p>如果你能赚到1000美元，你就能赚到10万美元。</p><p>随着你在这个过程中越做越熟练、学到越多，你每次赚到1000美元以上所需的时间就会越来越短。</p><p>我们要用最精简的方式来完成这件事。</p><ul><li>你不需要庞大的受众群体。</li><li>你只需要学会两项高收入技能的基础知识。</li><li>你所做的每一个行动都会复利累积，没有一个会被浪费。</li><li>只要你坚持下去，每次这样做，你赚到的都会超过1000美元。</li></ul><p>但首先，我要先说明一点。</p><p>如果你看这篇文章，是想找一个快速点一下“给我1000美元”按钮的捷径，那你大概会失败。</p><p>把那种“一夜暴富”的心态丢在门外吧。</p><p>如果你想掌控自己能赚多少钱，你就需要一家企业。简单明了，无可辩驳。</p><p>如果你开始创业，它所要求的性格特质，和朝九晚五的工作截然不同。你要为一切负责。你必须管理自己、发展自己，并学会去接纳创业过程中那些情绪上的起起落落。</p><p>你会被拒绝。</p><p>你会质疑自己是不是应该放弃，回到那种“刚好舒适到能生存、又刚好无痛到能一成不变”的生活里去。</p><p>求你了，看在一切神圣事物的份上，去坚持你明知自己需要做的、能让你掌控人生的那一件事。</p><p>这就是你的出路。</p><p>接下来我们要讨论的内容：</p><ul><li>在一个自由职业者和能动性公司主林立的世界里，建立受众为什么重要。</li><li>该谈些什么话题，该卖些什么东西。</li><li>微技能栈——学会两项高收入技能，如何为你铺就一个有利可图的未来。</li><li>微报价——如何不用花几个月打磨产品或服务，今天就开始拿下客户。</li><li>拿下客户的仅仅两种方法，让你在接下来60天里专注其中。</li><li>1000美元挑战。每一天都要采取的具体步骤，把这一切变成一家真正的企业。</li></ul><p>这篇文章其实是一份迷你课程，所以会有点长。</p><p>我们开始吧。</p><p>顺便一提：一人企业启动板（The One-Person Business Launchpad）在黑色星期五周末之前五折优惠。<a href="https://thedankoe.com/get/opbl" target="_blank" rel="noreferrer">点这里查看。</a></p><h2 id="搭建你的数字门店" tabindex="-1">搭建你的数字门店 <a class="header-anchor" href="#搭建你的数字门店" aria-label="Permalink to &quot;搭建你的数字门店&quot;">​</a></h2><p>你要在社交媒体上建立起你的受众。</p><p><strong>这是商业的第一课：</strong>你需要<em>流量</em>，才能把它导向你的产品或服务。现在花时间去建网站或设计logo，<em>不是</em>生产性的时间利用方式。</p><p>你开始时不需要百万粉丝，但我可以保证，未来你会需要一个不断增长的受众群体。</p><p>冷邮件和付费广告都不错，但有更好的方法能达到同样的效果，同时避免最后什么都没有留下的局面。</p><p>你可以发出1万封冷邮件，花1万美元投广告，但之后这些人都去哪儿了？通过在社交媒体上用内容建立受众，你能实现几件事：</p><ul><li>你能持续接触到关注你的人。</li><li>免费开始，不需要太多技能或许可。</li><li>你写的每一篇内容都在让你的受众逐渐“热身”，愿意购买。</li><li>你可以打造新产品，提高盈利能力。</li><li>人们关注你是因为你本人，你不会被困在某个特定的商业模式或技能里。</li><li>当你的受众足够大时，你可以离开客户外包工作，或者去打造你一直梦想的那个创业公司（你已经拥有客户，也拥有团队的潜在候选人，不需要花几十万美元去做营销和招聘）。</li></ul><p>话说到这，我们赶紧把你的社交媒体资料搭建起来。</p><h3 id="决定教什么、卖什么" tabindex="-1">决定教什么、卖什么 <a class="header-anchor" href="#决定教什么、卖什么" aria-label="Permalink to &quot;决定教什么、卖什么&quot;">​</a></h3><p>我之前已经用很多不同的方式讲过这个话题。</p><p>大多数时候，它都涉及创建某种“主题树”。</p><p><img src="'+t+'" alt=""></p><p>这种方法仍然有用，我也鼓励你去用，但我想让事情变得稍微简单一点。</p><p>你要<em>加入你已经身处其中的那个细分领域。</em></p><p>回答以下这些问题，然后选出最能满足大多数问题的1-3个话题：</p><ol><li>在你的搜索记录和YouTube观看历史里，有哪些<em>有价值</em>的内容？</li><li>你关注的那些账号在谈论什么？你觉得自己的知识水平和他们相近吗？</li><li>如果你现在要买一本新书，会是关于什么主题的？</li><li>当你购买一款教育类或有助于改善行为的产品时（比如计划本、软件，或健康补剂，不是指新衣服或其他生活必需品），你会买什么？</li></ol><p>在人生大多数领域，成功的关键都是<em>聪明的模仿。</em></p><p>我们所有人都在模仿。我们的大脑，是我们迄今接触到的所有信息复杂交织而成的产物。</p><p>人们其实把创业这件事想得太复杂了。</p><p>他们以为，如果别人都在做，那这个领域就已经饱和了。</p><p>不是的。</p><p>根本不是那样。</p><p>如果别人都在做，那恰恰说明它是有利可图的。说明人们真的想要它。</p><p>所以，你的任务是做同样的事，但让它变得稍微<em>独特</em>一点点。</p><p>我的创业公司Kortex，并没有什么革命性或全新的东西。</p><p>到处都在冒出各种笔记应用和“第二大脑”类的克隆产品。</p><p>真正让我们脱颖而出的，是我们基于自己在这个领域的经验——而大多数人没有这份经验——所添加的那些小功能，让它变得稍微好用一点点。我们还有分发渠道。未来几年，和Notion这样的产品竞争，对我们来说不算太大的挑战。其他一些应用可能就没那么有胜算了。</p><p>即便我们做不到Notion那样的规模，我们的团队规模和成本只是他们的一小部分，我们也没拿任何VC的钱，凭我们能拿下的这一小块市场，依然能达到八位数的年经常性收入（ARR）。</p><p>回到正题。</p><p>写下你已经在阅读的1-3个话题。这就是你内容创意的来源。</p><p>写下你已经购买过的1-3个课程、模板或产品。这些就是你将要重新定位的报价的起点。</p><p>只有当你真正开始写作和销售之后，你才会获得那些能让这些东西真正专属于你、独一无二的想法和反馈。</p><p>再读一遍上面那句话，把它牢牢刻进脑子里。</p><p>它不是我随便放进来、写完就会被遗忘的一句话。它是决定你整个创业旅程的关键一句。</p><h3 id="打造你的个人资料" tabindex="-1">打造你的个人资料 <a class="header-anchor" href="#打造你的个人资料" aria-label="Permalink to &quot;打造你的个人资料&quot;">​</a></h3><p>一个优秀的社交媒体资料页，本身就是个小小的成就。</p><p>你需要懂一点设计和/或摄影，才能做出一张好的头像和横幅图。</p><p>你需要懂文案写作，才能写出让人想关注你的简介。</p><p>你需要懂受众认知阶段和转化漏斗，才能确定简介里放的那个链接该指向哪里。</p><p>你需要懂社交媒体和写作，才能写出一篇有权威感、互动数据也不错的置顶帖（并且在结尾还能顺势引导到你转化漏斗的下一步）。</p><p>但你不该拿这个当借口，跑去教程地狱里拖延。不，你不需要去上一门设计课、文案课或转化漏斗课程。你需要的是快速做出一个资料页，然后开始测试。这才是真正学会这些技能的唯一方式。课程能帮你的是<em>提供可测试的技巧。</em>而技能，则是你测试过、筛选出能带来最大效果的那一整套技巧的集合。</p><p>这是做这件事最快的方法：</p><ul><li>看1-3个YouTube教程，学习怎么拍一张肖像照或制作头像。跟着做出你自己的。</li><li>用我们前面讲的方法写你的简介：你的主题，以及你想在其中建立权威的那个报价。</li></ul><p>我已经替你把测试都做好了。用这个简介模板：</p><p><em>我写关于[主题]的内容。[他们能从你的报价中获得的结果]。</em></p><p>如果我的主题是效率提升、写作和自我提升，而我想卖的东西是围绕写作展开的，那我的简介会是：</p><p><em>我写关于效率提升、写作和自我提升的内容。学习把写作变成一项高收入技能。</em></p><p>接着，我会链接我报价的第一步——这个我们会在“微报价”那一节里讲到。</p><p>如果你觉得自己的简介还不够好，没关系，别为此纠结。就照现在这样，开始写内容吧。从大局来看，简介没那么重要。人们看一两次就会忘掉。真正带来关注者和销售的，是你的内容。你的任务是把内容写得足够好，好到简介写什么都不重要。</p><p>最后，用一个问题来指导你打造资料页：</p><p><strong>它看起来像是应该拥有100万粉丝的那种资料页吗？</strong></p><p>如果不是，那就在接下来的6到12个月里慢慢改进，直到它做到为止。</p><p>即便它还没做到，你依然可以获得关注者、赚到收入。</p><h2 id="微技能栈" tabindex="-1">微技能栈 <a class="header-anchor" href="#微技能栈" aria-label="Permalink to &quot;微技能栈&quot;">​</a></h2><p>作为一人企业，你最终需要学会经营一家完整企业所需的每一项技能（除了实体分销和商业地产这类）。</p><p>我们这里说的“微创作者”，只是一个起步的方式。我假设这将成为你毕生的事业，所以别因为把你带到这篇文章的那种“一夜暴富”心态，而在你的长期潜力上贪图省事、偷工减料。</p><p>现在，要开始创造收入，你只需要几样东西：</p><ol><li>一个流量来源</li><li>一个可以出售的产品或服务</li></ol><p>所以，能简化这整个过程的两项技能，就是<em>写作</em>和<em>销售</em>。</p><p>写作是最容易上手的。你不需要设计或视频经验。你甚至不需要写得多好，你只需要写得有冲击力。所有社交媒体内容都是从写作开始的（是的，即便是视频脚本也一样）。</p><p>销售，是你把那些看你写的东西的人，转化成顾客的方式。</p><p>我们来学一下这两者的基础知识。</p><h3 id="用写作建立受众" tabindex="-1">用写作建立受众 <a class="header-anchor" href="#用写作建立受众" aria-label="Permalink to &quot;用写作建立受众&quot;">​</a></h3><p>社交媒体内容有两种类型：</p><p><strong>1）短帖</strong></p><p>这包括推文、reels、shorts、TikTok视频、Instagram帖子，以及基本上任何300字符以内或1分钟以内的内容。</p><p>我在任何平台上最喜欢的写作方式是：先写一条推文，然后把这条推文复制粘贴进类似Figma或Canva的图片模板里（你可以看看我的Instagram主页，看看写作以图片形式呈现是什么样子）。没错，在任何短内容平台上，你不需要发别的东西，只靠“写作”就能建立起受众。</p><p>短帖适合用来保持存在感、吸引受众，以及测试想法。</p><p>短帖是你的基本盘。你应该至少每天发一条。在X上，你可以每天发2-3条，用来测试哪些内容值得发到其他平台，或者扩展成一篇长帖。</p><p><strong>2）长帖</strong></p><p>这包括X上的推文串、Threads（Instagram旗下产品）里的帖子串、Instagram的图文轮播、LinkedIn上的长帖或轮播，或者我称之为“微文章”的东西——最近这种形式表现得相当不错。</p><p>这是一个微文章的例子：</p><p><img src="'+i+'" alt=""></p><p>无论是短帖还是长帖配图，妙处在于你可以把图片发到任何平台上。只要确保图片的尺寸是 4×5，这样就能适配 Instagram。</p><p>长帖是有策略性的。如果它们基于一个已经验证过的主题（比如你最好的一条短帖），就可能极度爆火。它们往往能带来更多粉丝。</p><p>问题是，它们需要更长的时间来写。你应该争取每周写 1-2 篇，并确保能让它们被转发出去，这样才有可能被更多受众看到。别指望算法来帮你增长。读一读我的信件《<a href="/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">如何在零粉丝的情况下打造受众</a>》，学习怎么做到这一点。</p><p>确保你人脉网络中的每个人每周都分享你的长帖。这才是增长之道。</p><p>你也可以在我的 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 课程中（含模板）学习整个流程。</p><p>总结一下：</p><p>在 X 上每天写 2-3 条短帖。</p><p>在 X 上每周写 1-2 篇长帖。</p><p>当你的粉丝达到 50,000+ 时，再考虑开始在其他平台发布内容。</p><p>为什么是 X？</p><p>除了 YouTube 之外，X 上的人群质量比大多数平台都高。</p><p>人们登录 Instagram、LinkedIn 或 TikTok 不是为了受教育。</p><p>X 就像 Reddit，只是稍微没那么毒，而且你可以关注真实的人。</p><p>你去 Reddit 通常是为了学到一些你之前不知道的东西。</p><p>而在 X 上，你需要做的就是把你的想法写出来。</p><p>然后，把你最好的内容拿出来，让在其他平台上的增长变得更容易。</p><p>把一个想法变成一条推文串，把推文串变成一份newsletter，把newsletter变成一个 YouTube 视频，把那个视频变成一份免费下载资料，把那份免费下载资料变成一个产品。这就是你验证一个好想法的流程。</p><p>那么，你到底该写什么？</p><p>拿出你之前选定的主题，做以下这些事：</p><ul><li>把它们拆解成常见的痛点，然后写如何解决这些痛点。</li><li>用像 <a href="https://chromewebstore.google.com/detail/tweet-hunter-x-sidebar-fo/amoldiondpmjdnllknhklocndiibkcoe?hl=en" target="_blank" rel="noreferrer">TweetHunter X Sidebar</a> 这样的工具研究其他账号的热门推文，并从你自己的视角重写它们。</li><li>读书，把社交媒体当成你记笔记的地方——但要把这些笔记写成带有钩子、正文和结论的内容。</li><li>去你最喜欢的 YouTube 频道，按最受欢迎筛选他们的视频。然后，把他们的标题当作你写钩子和帖子的起点。</li></ul><p>现在，开始写吧。</p><h3 id="销售流程" tabindex="-1">销售流程 <a class="header-anchor" href="#销售流程" aria-label="Permalink to &quot;销售流程&quot;">​</a></h3><p>销售就是讲故事。</p><p>你在向某人展示他们可以到达的地方，让他们意识到当前处境中的痛点，并<em>提供</em>一条从A点到B点的路径。</p><ul><li>痛点</li><li>期望的结果</li><li>到达那里的路径（最好是你独特的做法）</li></ul><p>这就是销售。</p><p>这就是内容。</p><p>这就是落地页。</p><p>这就是所有优秀且有说服力的东西的本质。这不仅仅是一堂关于销售的课，而是关于说服力本身的课，<a href="/letters/the-greatest-skill-of-the-21st-century">就像我们上周谈到的那样。</a></p><p>在你所处的每一种情境中都练习销售。写作、对话，以及尝试赚取收入时。</p><p>我们不会深入探讨像销售电话这样的流程，因为说实话，你不需要担心这个。</p><p>作为一名创作者，你 90% 的“销售”是通过内容完成的：</p><ul><li>让人们意识到他们的问题/痛点。</li><li>给他们提供可以测试和实验的解决方案。</li><li>描绘他们理想中的未来生活，让他们有一个期望的结果。</li></ul><p>大多数企业主没有打造受众所带来的那些便利条件。</p><p>我们将在下一节讨论一种更实际的销售方式。</p><h2 id="微报价-micro-offer" tabindex="-1">微报价（Micro Offer） <a class="header-anchor" href="#微报价-micro-offer" aria-label="Permalink to &quot;微报价（Micro Offer）&quot;">​</a></h2><p>直说重点：</p><p>微报价是一种你还不需要有任何现成产品就能提供的服务。</p><p>你只需要：</p><ul><li>一个作为你公开简历的社交媒体主页。</li><li>展示你权威性的内容（通过揭示问题并提供解决方案——也就是“提供价值”）。</li><li>能够给点赞、评论、转发或私信询问你帖子相关问题的人发消息的能力。</li><li>一份问卷，如果你没有先联系对方，让他们可以填写来表达兴趣。</li></ul><p>微报价是一种在你花时间去做之前，先<em>测试</em>你应该把什么打造成完整产品或服务的方式。</p><p>创建微报价最好的方法很简单。</p><p><strong>你提供一套包含 4 次每周一对一会议的套餐，价格为 1000 美元。</strong></p><p>这样做能实现几件事：</p><ul><li>1000 美元是一个扎实的价格。如果人们为此付费，就意味着其他人会为一个更完善的报价支付 3000-10000 美元，具体取决于你的目标受众（企业家和企业主通常不会对这么高的价格皱眉……1000 美元是大多数人如果真心想要的话都能承担得起的（现在别让局限性信念和你缺乏经验的想法占了上风））。</li><li>4 次每周会议的时间足够让你的客户获得成果。</li><li>只有少数人能从你替他们做事（自由职业工作）中受益。而<em>任何人</em>都能从你通过通话<em>教</em>他们中受益。如果你愿意，可以把这称为教练或咨询。</li><li>在卖出几次这样的服务之后，你可以判断出什么内容应该纳入一个完整的产品或服务中。</li></ul><p>那么，这 4 次通话里你要包含什么内容？</p><h3 id="微报价框架" tabindex="-1">微报价框架 <a class="header-anchor" href="#微报价框架" aria-label="Permalink to &quot;微报价框架&quot;">​</a></h3><p>我们需要一个起点。</p><p>一个你有信心能交付的东西。</p><p><strong>第一步）识别一个大问题</strong></p><p>结合你在某方面有一定经验的主要主题，人们面临的一个大问题是什么？</p><p>你可以通过以下几种方式找到这个问题：</p><ul><li>写关于不同问题的内容，看哪一个获得最多的互动。</li><li>研究关于该主题的 YouTube 视频，看哪些获得了大量观看，并观看视频以识别它们在那个视频中所针对的问题（所有内容都针对某个问题）。</li><li>关注谈论那个主题的社交媒体账号，看他们哪些与问题相关的帖子表现最好。</li></ul><p>大问题应该属于健康、财富和关系这三个永恒市场之下。你的任务是瞄准其中一个，并围绕它定位你的兴趣。</p><p>如果我的兴趣是效率，一个大问题就是没有时间或精力让配偶感受到被爱（关系）以及在职业上取得进步（财富）。</p><p>你可以通过描绘<em>这些问题会给人们的生活带来什么后果</em>来深入挖掘。在这个例子中，他们的关系会变得死气沉沉、无聊，导致不必要的压力和一些小问题堆积成精神上的混乱。你越能描绘出某人生活中正在发生的事情，效果就越好。</p><p>（把这些都用在内容创作中。）</p><p>如果我的兴趣是编程或写作，一个大问题就是没有一项能让你赚更多钱的技能。你被学校体系慢慢推向一个与你的技能栈毫不相关的职业。那条路耗尽了你用生命去做更多事情的精力，并用各种责任把你捆住。</p><p>注意到我不仅是在揭示问题，还在放大它吗？这一点很重要。可能是你的营销邮件、落地页和内容中最重要的部分。</p><p>别把这个问题想成是与你选择的主题或兴趣直接相关的东西。</p><p>这个问题是<em>人们生活中已经在经历的一个痛点</em><em><strong>，而你的主题或兴趣能解决它。</strong></em></p><p>某人生活中的一个大问题是什么，你的兴趣如何能帮助解决它？</p><p><strong>第二步）描绘一种期望的生活方式</strong></p><p>问题的反面是什么？</p><p>他们想要实现的目标是什么？</p><p>一旦他们达到了那个目标，他们的生活会是什么样子？</p><p>写下他们理想一天的 3 个方面。</p><p>对于像效率这样的主题，可能是：</p><ol><li>醒来后做你喜欢的工作</li><li>中午过后不再感到疲惫和昏沉，这样你就能把工作完成</li><li>睡得安稳，因为你知道自己没有一堆会造成压力的遗留任务</li></ol><p>如果你愿意，可以把这些内容规划得更详细一些。</p><p><strong>第三步）创建一套独特的流程</strong></p><p>那么，你的实际报价是什么？</p><p>你要在你的会议中带领人们完成什么？</p><p>你最终能把这些变成什么产品或完整的服务？</p><p>你需要一套属于自己的独特流程或系统，并且能够持续改进它。</p><p>对于我的 2-Hour Writer 课程来说，那就是三点内容生态系统（3 Point Content Ecosystem）。</p><p>你要怎么想出这个东西？</p><ol><li>把某人需要经历的每一步都写下来，从第一步（大问题，也就是他们现在所处的位置）到第二步（他们期望的生活方式）。</li><li>回顾这些步骤，稍微打磨一下。创建一套你相信对你帮助的人有效的系统。</li><li>给这个流程起一个有吸引力的名字。这就是激发潜在客户欲望的东西。我创造了很多名字，正是它们带来了我今天拥有的受众，比如 The One Person Business（一人企业）、The 4 Hour Workday（4小时工作日）、The Mastery Method（精通法）等等。我在大多数内容中都练习给东西命名（这一个就是Micro Creator（微创作者），我敢说你们大多数人正是因为它才来到这里）。</li></ol><p>我们不必让它变得比这更复杂。</p><p>在你和客户的 4 次会议中，你要把你写下的步骤拆分成能在这 4 次会议里可管理的部分。</p><p>作为附加福利，你可以为客户创建一个项目，引导他们完成这些步骤（比如一份效率规划表、健身计划、写一份newsletter，或者编程一个小应用）。</p><p>这就是你完整的报价：</p><ul><li>你解决的问题</li><li>期望的结果</li><li>连接差距的独特流程</li></ul><p>在你和人们合作的过程中，你的重点应该放在改进你的报价和收集客户见证上。</p><h3 id="创建一份资格筛选问卷" tabindex="-1">创建一份资格筛选问卷 <a class="header-anchor" href="#创建一份资格筛选问卷" aria-label="Permalink to &quot;创建一份资格筛选问卷&quot;">​</a></h3><p>我们大多数的客户会来自内容。</p><p>但是，我们需要一个让人们表达合作意愿的地方。</p><p>通常，这会是一个落地页，甚至是一个展示你产品或服务的完整网站。</p><p>现在，先把那个忘掉。这没有必要。</p><p>注册 JotForm、TypeForm，或者使用 Google Forms。</p><p>把表单名称设为“与我一对一合作”</p><p>把描述写成“实施 [你的独特流程]”</p><p>包含以下与你的报价相关的问题：</p><ol><li>姓名</li><li>邮箱</li><li>社交媒体账号（这样你就能联系到他们）</li><li>你最大的困扰是什么？（提供与你的主题和报价相关的多选答案）</li><li>你希望在 30 天后达到什么状态？（提供与你的主题和报价相关的多选答案）</li><li>“这不是一项免费服务。你是否认真考虑一起合作来实现 [期望的结果]？”（是或否选项）</li></ol><p>简短、精炼，切中要点。</p><p>第4个问题让潜在客户意识到自己的问题。</p><p>第5个问题激发改变的欲望。</p><p>第6个问题在他们心中种下付费的想法。</p><p>你要把这份问卷放在你的内容下方以及你的个人简介链接中。</p><p>但接下来我们该做什么？我们又该如何搞定那些没有填写问卷的客户？</p><h3 id="私信的艺术" tabindex="-1">私信的艺术 <a class="header-anchor" href="#私信的艺术" aria-label="Permalink to &quot;私信的艺术&quot;">​</a></h3><p>当你开始看在线商业教程时，几乎总会有人告诉你要冷邮件或冷私信别人，去为一项你几乎没有任何经验的技能拉客户。</p><p>我们已经拥有一个你至少有一定了解的报价了。</p><p>现在，我们需要私信那些<em>已经喜欢你、想和你交流、并且是你产品潜在客户的人。</em></p><p>避免给随机的人发消息。你很可能会在私信里和主页动态上被吐槽。</p><p><strong>你要私信谁？</strong></p><ul><li>在与你的产品相关的帖子下评论的人</li><li>转发或分享你相关帖子的人</li><li>主动私信你提问或打招呼的人</li><li>填写了你的资格问卷的人</li></ul><p>在我们了解私信里该说什么之前，先来了解一下我们称之为“磁性内容”的东西。</p><p>磁性内容是指围绕痛点、好处、理想生活方式、快速技巧、对常见建议的个人见解、对其他账号高表现内容的改写，以及克服痛点的可行步骤所写的短帖或长帖……所有内容都与你的产品相关。</p><p>一旦你确定了你的产品，围绕它写内容应该相对简单。</p><p><em>评论或分享这些帖子的人，就是对该话题表达兴趣的人。他们是以温和方式接触的最佳对象。他们已经认识你，并且认为你有一定的权威性。</em></p><p>（旁注：如果你是在 YouTube 上做这件事，你没法私信别人，所以你需要让大家去填写资格问卷，然后通过邮件联系他们，或在像 Instagram 这样的平台上私信他们）。</p><p><strong>那么，你在私信里该说什么呢？</strong></p><p><strong>1）从对话中断的地方接上话题。</strong></p><p>如果他们评论或分享了你的某个帖子，<em>给他们发那条帖子的链接</em>，并在私信里对他们的评论进行“回复”。</p><p>如果你是在他们提交问卷后私信他们，你的任务是简要地再带他们过一遍问卷里的所有问题。</p><p>以这样的话开头：<em>“嗨[名字]，我看到你提交了想和我合作的表单。能跟我多说说你为什么填写它吗？你想从和我的合作中得到什么？”</em></p><p><strong>2）问问他们的进展如何。</strong></p><p>假设他们对他们互动过的帖子话题感兴趣，问问他们是不是在学习这个，或者进展如何。</p><p>对于健身这类话题，<em>“减重之旅进行得怎么样？有什么我能帮上忙的吗？”</em></p><p>这既让他们想起了自己渴望的生活方式，又让他们意识到自己的卡点所在。</p><p>如果你是在回复他们的问卷，问问他们为解决自己列出的问题做了些什么。</p><p><strong>3）给他们提供新颖的建议，并提及你的产品。</strong></p><p>到这个时候，你应该已经知道自己能不能帮到他们了。</p><p>先给出一些免费的价值和知识。这能证明你的权威性。</p><p>针对他们在第2步里说的内容给出建议，并尽量让它不那么基础。对于健身或效率这类话题，告诉他们“多喝水”只会让他们觉得跟你合作不值得。要证明你懂这一行。</p><p>在这条消息的末尾，提及“其实我提供一套4次的辅导包来帮你解决这个问题。我帮你落实[你独特的方法]，说白了就是让你更容易达到[期望的结果]。总费用和一个好的私人教练差不多——4次课1000美元。”</p><p>如果你是在回复他们的问卷，把最后一段换成解释你的产品接下来的流程。你可以提到，如果他们感兴趣，你会发给他们每次通话要谈的内容、他们如何安排通话时间、他们要做的项目，以及附带的1000美元发票。</p><p>没错，就直接说出价格。</p><p><strong>4）处理异议，发送发票。</strong></p><p>销售电话会有帮助，但你不一定需要它。如果他们要求在电话里过一遍，那值得去做。</p><p>一开始你可能会收到不少拒绝。没关系。刚起步做生意就是这样。</p><p>记住，我们的目标是在60天内赚到1000美元。在你有了第一个客户和客户见证之后，速度会快得多。</p><p>这时候，回答他们提出的任何问题。</p><p>他们问完之后，给他们发一个用Stripe或Paypal生成的发票链接。</p><h2 id="_60天行动计划" tabindex="-1">60天行动计划 <a class="header-anchor" href="#_60天行动计划" aria-label="Permalink to &quot;60天行动计划&quot;">​</a></h2><p>你会感到困惑和不知所措。</p><p>学习新东西时就是这样的。</p><p>你的大脑在努力扩展和成长。就像举重之后你会浑身酸痛一样。</p><p>大部分成果会在第30天之后到来。</p><p>如果你还没取得什么值得一提的成果，你可能没意识到，这本身就是一个自然的筛选机制，把那些对这件事不认真的人筛掉。</p><p>我在一个视频爆火、真正感觉到我的YouTube频道在增长之前，发了80个视频。</p><p>所有值得拥有的东西都是这样：先什么都不发生，然后一切都发生了。</p><p>你觉得自己毫无进展，然后你的经验积累、复合，最终变成一个人说出“好的”。</p><p>以下是你该专注的事情。</p><p>无论你是否能立即看到结果（有些人会），都要停止做多巴胺瘾君子，给自己完整的60天去赚到第一笔1000美元。</p><p><strong>1）建立一个主页，然后不要再为它烦恼。</strong></p><p>不，改改你的简介并不会神奇地让你每月赚10000美元。</p><p>建好你的主页，然后就忘了它。</p><p><strong>2）每天写3-5条短帖。</strong></p><p>通常我建议每天发1-2条短帖，那是我自己的做法。</p><p>你可能觉得1-2条更容易，但其实不是。想法生出想法。写得越多，你的想法就越多，学到的东西也越多，感觉自己进步也越大。</p><p>以下是具体做法：</p><ul><li>开始建立一个“灵感收藏库”，收集你喜欢并想再创作的他人内容（保存好的推文、帖子、视频等）</li><li>在你消费内容、听播客、读书或聊天时随手记下想法</li><li>围绕挣扎、解决方案、方法教程、拆解分析、对你不认同的建议的评论等，写与你的产品相关的内容。</li></ul><p>我用<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>来做这一切。我会在下周的<a href="https://youtube.com/c/DanKoeTalks" target="_blank" rel="noreferrer">YouTube视频</a>里展示我的设置——或者阅读<a href="/letters/the-greatest-skill-of-the-21st-century">上周的信件/视频</a>来了解这个流程。</p><p>每天，记得翻看你的评论和转发，去私信这些人。</p><p>每天或隔一天，附上你问卷的链接和行动号召，以吸引更多感兴趣的人来私信你。</p><p><strong>3）每周写1-2条长帖。</strong></p><p>你留住注意力的时间越长，人们就越信任你，你能传递的价值也越多。这就是为什么我写这么长的通讯。人们不需要另一个理由来学我的课程或试用Kortex。</p><p>通讯不属于“微型创作者”工作流的一部分。等你把其他一切都搞定了再加进来。我们在<a href="https://thedankoe.com/opbl" target="_blank" rel="noreferrer">一人企业启动计划</a>中详细拆解了这一切。</p><p>对于长帖，你要做类似的事情：</p><ul><li>拿出你最好的帖子（或别人最好的想法），在一个推文串、微型文章（<a href="https://x.com/thedankoe/status/1824463895894835480" target="_blank" rel="noreferrer">例子</a>）或长帖里展开论述。</li><li>利用额外的空间分享额外的秘诀。尽量至少包含一件不是常见建议或常识的内容。</li><li>在每篇的末尾都放上你的问卷链接。</li></ul><p>我个人推荐写推文串。推文串是把多条推文串联在一起。你之前见过，就是一条推文接一条推文，作为对彼此的评论。</p><p>它们的结构使其更能留住注意力（更易读），能把读者直接引导到行动号召处（带来更多销售），并且很容易被改编成YouTube视频、Instagram轮播图或LinkedIn轮播图。而且，其中的每条推文都可以单独变成新的推文。</p><p>长帖将是你增长和销售的主要燃料。不要忽视它们。</p><p>但是，长帖只有在被人看到时才有意义。</p><p><strong>4）让你的帖子被人看到。</strong></p><p>在这封信里我们没怎么谈这个（因为我在其他信里已经喋喋不休了），但算法很可能不会让你一夜成名。</p><p>大多数人没有意识到，社交媒体的增长来自<em>人工努力和技巧。</em>一旦你意识到这一点，你就不再把它看作是那些受欢迎的人靠运气取胜的游戏。</p><p>你需要回复大账号和小账号。</p><p>你需要私信别人来交朋友，一起成长。</p><p>你需要写标注别人的推文串，让他们有理由转发你的内容。</p><p>你可以在《<a href="/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">如何在零粉丝的情况下建立受众</a>》中学到如何做这一切。</p><p>任何告诉你不需要做这些事的人，可能只是想给你一个不真实、只迎合算法的方法。</p><p>如果你想按自己喜欢的方式、写自己想写的内容，算法很可能不会喜欢它——或者你运气好，蹭上了一波热点，然后当平台改变时，又困惑于为什么自己不再增长了。</p><p><strong>5）规划你的微型产品。</strong></p><p>你现在还不需要一个成型的产品或服务。</p><p>你只需要一件事：（1）你在这方面高于平均水平，（2）它能帮人解决生活中一个实际的问题。</p><p>想想你擅长什么。</p><p>其他人想学这个东西吗？他们已经在学习它了吗？有没有围绕它建立起的一个行业？你有没有关注一些靠它谋生的人？</p><p>很好，你已经拥有了打造一个百万美元公司所需的一切。这不是开玩笑。你正身处一个关于人们如何赚钱的活生生的教程之中。</p><p>我不是无缘无故坐在这写这些通讯的。是的，我很喜欢写它们，非常喜欢（否则我会去做一些更赚钱的事），但我写它们是因为它们能为我的业务创造收入。</p><p>你读的每一篇内容、访问的每个落地页、读的每封邮件、读的每本书等等，背后都关联着金钱。</p><p>你没赚到钱，是因为你没有创作并销售这些东西。</p><p>现在，你所需要的只是一套4次通话、售价1000美元的产品包，去教别人一些能让他们生活受益的东西。</p><p>健身、一项技能、营养、编程，等等等等。</p><p>选一件事，然后提出帮别人解决它。</p><p>一旦你开始获得成果并了解人们想要什么，就投入更多时间去打造一个“真正的”企业。</p><p><strong>6）每周发30条私信。</strong></p><p>这听起来数量很大，但其实非常低，低到近乎可怜。</p><p>那些每月发出数千封冷邮件的自由职业者和能动性所有者，如果听到你抱怨一个月发30条消息，会当面笑你。</p><p>但是，每周30条私信乘以8周，等于210条私信。</p><p>你只需要不到0.5%的接触对象对一个1000美元的产品说“好”。这完全是可能实现的。</p><p>但是，你可能没意识到的是，即使你只成交了一个客户，你也已经建立起了一个庞大的人脉网络。</p><p>你与210个人有了直接联系。你的粉丝可能增长了几百人。大约1000人会理解你的专业能力。他们每个人又认识50到500个人，可以向他们介绍你。</p><p>你坚持得越久，越多人对你说好，你的受众也会越壮大，很快你就会有人像从天而降一样，找你合作。</p><p>这封信就到这里。</p><p>希望它对你有所帮助。</p><p>——丹·科伊（Dan Koe）</p><hr><p><a href="/en/letters/the-minimalist-creator-business-make-your-first-1000-in-60-days">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',299))])}const q=a(d,[["render",c]]);export{P as __pageData,q as default};
